      ex: { prompt: 'Write solveNQueens(n) returning all boards (arrays of strings with "Q" and ".") with n non-attacking queens, in the order found by trying columns left to right row by row.', py: "def solveNQueens(n):\n    out, cols, diag1, diag2, placed = [], set(), set(), set(), []\n    def go(r):\n        if r == n:\n            out.append(['.' * c + 'Q' + '.' * (n - c - 1) for c in placed])\n            return\n        for c in range(n):\n            if c in cols or r - c in diag1 or r + c in diag2:\n                continue\n            cols.add(c); diag1.add(r - c); diag2.add(r + c); placed.append(c)\n            go(r + 1)\n            cols.remove(c); diag1.remove(r - c); diag2.remove(r + c); placed.pop()\n    go(0)\n    return out\n", sig: "(int n) -> string[][]", java: "class Solution {\n    public List<List<String>> solveNQueens(int n) {\n        List<List<String>> out = new ArrayList<>();\n        place(n, 0, new int[n], new boolean[n], new boolean[2 * n], new boolean[2 * n], out);\n        return out;\n    }\n    private void place(int n, int r, int[] cols, boolean[] used, boolean[] diag, boolean[] anti, List<List<String>> out) {\n        if (r == n) {\n            List<String> board = new ArrayList<>();\n            for (int c : cols) {\n                char[] row = new char[n];\n                Arrays.fill(row, '.');\n                row[c] = 'Q';\n                board.add(new String(row));\n            }\n            out.add(board);\n            return;\n        }\n        for (int c = 0; c < n; c++) {\n            if (used[c] || diag[r - c + n] || anti[r + c]) continue;\n            used[c] = diag[r - c + n] = anti[r + c] = true;\n            cols[r] = c;\n            place(n, r + 1, cols, used, diag, anti, out);\n            used[c] = diag[r - c + n] = anti[r + c] = false;\n        }\n    }\n}\n", cpp: "class Solution {\npublic:\n    vector<vector<string>> solveNQueens(int n) {\n        vector<vector<string>> out;\n        vector<string> board(n, string(n, '.'));\n        vector<bool> used(n), diag(2 * n), anti(2 * n);\n        place(n, 0, board, used, diag, anti, out);\n        return out;\n    }\nprivate:\n    void place(int n, int r, vector<string>& board, vector<bool>& used, vector<bool>& diag, vector<bool>& anti, vector<vector<string>>& out) {\n        if (r == n) { out.push_back(board); return; }\n        for (int c = 0; c < n; c++) {\n            if (used[c] || diag[r - c + n] || anti[r + c]) continue;\n            used[c] = diag[r - c + n] = anti[r + c] = true;\n            board[r][c] = 'Q';\n            place(n, r + 1, board, used, diag, anti, out);\n            board[r][c] = '.';\n            used[c] = diag[r - c + n] = anti[r + c] = false;\n        }\n    }\n};\n", fn: 'solveNQueens', params: 'n', cases: [{ args: [4], expect: [['.Q..', '...Q', 'Q...', '..Q.'], ['..Q.', 'Q...', '...Q', '.Q..']] }, { args: [1], expect: [['Q']] }, { args: [3], expect: [] }], solution: "function solveNQueens(n){const o=[],cs=new Set(),a=new Set(),b=new Set(),p=[];const d=r=>{if(r===n){o.push(p.map(c=>'.'.repeat(c)+'Q'+'.'.repeat(n-c-1)));return}for(let c=0;c<n;c++){if(cs.has(c)||a.has(r-c)||b.has(r+c))continue;cs.add(c);a.add(r-c);b.add(r+c);p.push(c);d(r+1);cs.delete(c);a.delete(r-c);b.delete(r+c);p.pop()}};d(0);return o}", hint: 'One queen per row; track used columns, r - c, and r + c.' },
